    private fun backgroundThreadFactory(name: String): ThreadFactory = ThreadFactory { runnable ->
        Thread({
            try {
                Process.setThreadPriority(Process.THREAD_PRIORITY_BACKGROUND)
            } catch (_: Throwable) {
            }
            runnable.run()
        }, name).apply {
            isDaemon = true
            priority = Thread.NORM_PRIORITY - 1
        }
    }

